-- Phase 78-82: Migrate embeddings from 768d to 1024d\n-- Gemma-3 VLM output size\n\n-- Enable pgvector extension\nCREATE EXTENSION IF NOT EXISTS vector;\n\n-- Create new table with 1024d vectors\nCREATE TABLE IF NOT EXISTS legal_embeddings_omni (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    \n    -- Core embedding (1024d)\n    embedding_vector VECTOR(1024) NOT NULL,\n    embedding_hash TEXT NOT NULL UNIQUE,\n    \n    -- Modality information\n    modality TEXT NOT NULL CHECK (modality IN ('text', 'image', 'multimodal')),\n    \n    -- Document metadata\n    file_path TEXT NOT NULL,\n    chunk_id TEXT NOT NULL,\n    language TEXT DEFAULT 'english',\n    \n    -- Seal/signature detection (from YOLO)\n    seals JSONB DEFAULT '[]'::jsonb,\n    seal_confidence FLOAT DEFAULT 0.0,\n    \n    -- Layout information (from DocLing)\n    layout_boxes JSONB DEFAULT '[]'::jsonb,\n    layout_type TEXT,  -- 'header', 'body', 'footer', 'table', 'form'\n    \n    -- OCR text (from TrOCR)\n    ocr_text TEXT,\n    ocr_confidence FLOAT DEFAULT 0.0,\n    \n    -- Citation graph\n    citations JSONB DEFAULT '[]'::jsonb,\n    authority_score FLOAT DEFAULT 0.5,\n    \n    -- California Constitution specific\n    ca_const_article TEXT,\n    ca_const_section TEXT,\n    ca_const_subsection TEXT,\n    \n    -- Timestamps\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    \n    -- Metadata\n    metadata JSONB DEFAULT '{}'::jsonb\n);\n\n-- Create indexes for efficient querying\nCREATE INDEX idx_legal_embeddings_omni_vector ON legal_embeddings_omni USING ivfflat (embedding_vector vector_cosine_ops) WITH (lists = 100);\nCREATE INDEX idx_legal_embeddings_omni_file_path ON legal_embeddings_omni (file_path);\nCREATE INDEX idx_legal_embeddings_omni_chunk_id ON legal_embeddings_omni (chunk_id);\nCREATE INDEX idx_legal_embeddings_omni_modality ON legal_embeddings_omni (modality);\nCREATE INDEX idx_legal_embeddings_omni_ca_const ON legal_embeddings_omni (ca_const_article, ca_const_section);\nCREATE INDEX idx_legal_embeddings_omni_authority ON legal_embeddings_omni (authority_score DESC);\nCREATE INDEX idx_legal_embeddings_omni_seal_confidence ON legal_embeddings_omni (seal_confidence DESC);\nCREATE INDEX idx_legal_embeddings_omni_created_at ON legal_embeddings_omni (created_at DESC);\n\n-- Create JSONB indexes for faster queries\nCREATE INDEX idx_legal_embeddings_omni_seals_gin ON legal_embeddings_omni USING GIN (seals);\nCREATE INDEX idx_legal_embeddings_omni_layout_gin ON legal_embeddings_omni USING GIN (layout_boxes);\nCREATE INDEX idx_legal_embeddings_omni_citations_gin ON legal_embeddings_omni USING GIN (citations);\nCREATE INDEX idx_legal_embeddings_omni_metadata_gin ON legal_embeddings_omni USING GIN (metadata);\n\n-- Create view for California Constitution embeddings\nCREATE OR REPLACE VIEW ca_constitution_embeddings AS\nSELECT \n    id,\n    embedding_vector,\n    ca_const_article,\n    ca_const_section,\n    ca_const_subsection,\n    ocr_text,\n    authority_score,\n    seal_confidence,\n    layout_boxes,\n    created_at\nFROM legal_embeddings_omni\nWHERE ca_const_article IS NOT NULL\nORDER BY authority_score DESC, created_at DESC;\n\n-- Create view for multimodal embeddings (with seals)\nCREATE OR REPLACE VIEW multimodal_embeddings_with_seals AS\nSELECT \n    id,\n    embedding_vector,\n    modality,\n    file_path,\n    chunk_id,\n    seals,\n    seal_confidence,\n    layout_boxes,\n    ocr_text,\n    authority_score,\n    created_at\nFROM legal_embeddings_omni\nWHERE modality = 'multimodal' AND seal_confidence > 0.0\nORDER BY seal_confidence DESC, created_at DESC;\n\n-- Create view for high-authority legal documents\nCREATE OR REPLACE VIEW high_authority_embeddings AS\nSELECT \n    id,\n    embedding_vector,\n    file_path,\n    chunk_id,\n    authority_score,\n    ca_const_article,\n    ca_const_section,\n    citations,\n    created_at\nFROM legal_embeddings_omni\nWHERE authority_score >= 0.8\nORDER BY authority_score DESC, created_at DESC;\n\n-- Create function for cosine similarity search\nCREATE OR REPLACE FUNCTION search_embeddings_cosine(\n    query_embedding VECTOR(1024),\n    limit_results INT DEFAULT 10,\n    min_similarity FLOAT DEFAULT 0.5\n)\nRETURNS TABLE (\n    id UUID,\n    file_path TEXT,\n    chunk_id TEXT,\n    modality TEXT,\n    similarity FLOAT,\n    seal_confidence FLOAT,\n    authority_score FLOAT,\n    ca_const_article TEXT,\n    ca_const_section TEXT,\n    created_at TIMESTAMP\n) AS $$\nSELECT \n    legal_embeddings_omni.id,\n    legal_embeddings_omni.file_path,\n    legal_embeddings_omni.chunk_id,\n    legal_embeddings_omni.modality,\n    1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) as similarity,\n    legal_embeddings_omni.seal_confidence,\n    legal_embeddings_omni.authority_score,\n    legal_embeddings_omni.ca_const_article,\n    legal_embeddings_omni.ca_const_section,\n    legal_embeddings_omni.created_at\nFROM legal_embeddings_omni\nWHERE 1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) >= min_similarity\nORDER BY similarity DESC\nLIMIT limit_results;\n$$ LANGUAGE SQL;\n\n-- Create function for duplicate detection (>95% similarity)\nCREATE OR REPLACE FUNCTION detect_duplicate_embeddings(\n    query_embedding VECTOR(1024),\n    similarity_threshold FLOAT DEFAULT 0.95\n)\nRETURNS TABLE (\n    id UUID,\n    file_path TEXT,\n    chunk_id TEXT,\n    similarity FLOAT,\n    created_at TIMESTAMP\n) AS $$\nSELECT \n    legal_embeddings_omni.id,\n    legal_embeddings_omni.file_path,\n    legal_embeddings_omni.chunk_id,\n    1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) as similarity,\n    legal_embeddings_omni.created_at\nFROM legal_embeddings_omni\nWHERE 1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) >= similarity_threshold\nORDER BY similarity DESC\nLIMIT 1;\n$$ LANGUAGE SQL;\n\n-- Create function for authority-weighted search\nCREATE OR REPLACE FUNCTION search_embeddings_authority_weighted(\n    query_embedding VECTOR(1024),\n    limit_results INT DEFAULT 10,\n    min_similarity FLOAT DEFAULT 0.5\n)\nRETURNS TABLE (\n    id UUID,\n    file_path TEXT,\n    chunk_id TEXT,\n    similarity FLOAT,\n    authority_score FLOAT,\n    weighted_score FLOAT,\n    ca_const_article TEXT,\n    ca_const_section TEXT,\n    created_at TIMESTAMP\n) AS $$\nSELECT \n    legal_embeddings_omni.id,\n    legal_embeddings_omni.file_path,\n    legal_embeddings_omni.chunk_id,\n    1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) as similarity,\n    legal_embeddings_omni.authority_score,\n    (1 - (legal_embeddings_omni.embedding_vector <=> query_embedding)) * legal_embeddings_omni.authority_score as weighted_score,\n    legal_embeddings_omni.ca_const_article,\n    legal_embeddings_omni.ca_const_section,\n    legal_embeddings_omni.created_at\nFROM legal_embeddings_omni\nWHERE 1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) >= min_similarity\nORDER BY weighted_score DESC\nLIMIT limit_results;\n$$ LANGUAGE SQL;\n\n-- Create function for California Constitution search\nCREATE OR REPLACE FUNCTION search_ca_constitution(\n    query_embedding VECTOR(1024),\n    article TEXT DEFAULT NULL,\n    limit_results INT DEFAULT 10\n)\nRETURNS TABLE (\n    id UUID,\n    ca_const_article TEXT,\n    ca_const_section TEXT,\n    ca_const_subsection TEXT,\n    similarity FLOAT,\n    authority_score FLOAT,\n    ocr_text TEXT,\n    created_at TIMESTAMP\n) AS $$\nSELECT \n    legal_embeddings_omni.id,\n    legal_embeddings_omni.ca_const_article,\n    legal_embeddings_omni.ca_const_section,\n    legal_embeddings_omni.ca_const_subsection,\n    1 - (legal_embeddings_omni.embedding_vector <=> query_embedding) as similarity,\n    legal_embeddings_omni.authority_score,\n    legal_embeddings_omni.ocr_text,\n    legal_embeddings_omni.created_at\nFROM legal_embeddings_omni\nWHERE legal_embeddings_omni.ca_const_article IS NOT NULL\n  AND (article IS NULL OR legal_embeddings_omni.ca_const_article = article)\nORDER BY similarity DESC\nLIMIT limit_results;\n$$ LANGUAGE SQL;\n\n-- Create trigger for updated_at timestamp\nCREATE OR REPLACE FUNCTION update_legal_embeddings_omni_timestamp()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = CURRENT_TIMESTAMP;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER legal_embeddings_omni_timestamp\nBEFORE UPDATE ON legal_embeddings_omni\nFOR EACH ROW\nEXECUTE FUNCTION update_legal_embeddings_omni_timestamp();\n\n-- Grant permissions\nGRANT SELECT, INSERT, UPDATE, DELETE ON legal_embeddings_omni TO postgres;\nGRANT SELECT ON ca_constitution_embeddings TO postgres;\nGRANT SELECT ON multimodal_embeddings_with_seals TO postgres;\nGRANT SELECT ON high_authority_embeddings TO postgres;\nGRANT EXECUTE ON FUNCTION search_embeddings_cosine TO postgres;\nGRANT EXECUTE ON FUNCTION detect_duplicate_embeddings TO postgres;\nGRANT EXECUTE ON FUNCTION search_embeddings_authority_weighted TO postgres;\nGRANT EXECUTE ON FUNCTION search_ca_constitution TO postgres;\n\n-- Log migration\nINSERT INTO schema_migrations (version, description, executed_at)\nVALUES ('20251125_001', 'Migrate embeddings from 768d to 1024d (Gemma-3 VLM)', CURRENT_TIMESTAMP);\n"